package vn.iotstar.security;import org.springframework.security.core.*;import org.springframework.security.core.userdetails.UserDetails;import vn.iotstar.entity.User;import java.util.*;public class CustomUserDetails implements UserDetails{final Long id;final String username;final String password;final boolean enabled;final Collection<? extends GrantedAuthority> authorities;public CustomUserDetails(User u){id=u.getId();username=u.getUsername();password=u.getPassword();enabled=u.isEnabled();authorities=List.of((GrantedAuthority)()->u.getRole().getName());}public Long getId(){return id;}public Collection<? extends GrantedAuthority> getAuthorities(){return authorities;}public String getPassword(){return password;}public String getUsername(){return username;}public boolean isEnabled(){return enabled;}}
